import { getGuideSessionId, getSessionId, trackEvent, trackPageView } from './analytics';

beforeEach(() => {
  sessionStorage.clear(); localStorage.clear();
  process.env.REACT_APP_BACKEND_URL = 'http://localhost:8005';
});

test('campaign source collection never persists the full query or referrer', () => {
  window.history.replaceState({}, '', '/?utm_source=linkedin&private_detail=do-not-store');
  trackPageView('landing');
  const [event] = JSON.parse(localStorage.getItem('ayana_local_events'));
  expect(event.meta.source).toBe('linkedin');
  expect(event.path).toBe('/');
  expect(JSON.stringify(event)).not.toContain('do-not-store');
  expect(event.session_id).toMatch(/^s_/);
});

test('unknown campaigns use a bounded source category', () => {
  window.history.replaceState({}, '', '/?utm_source=unrecognized-company');
  trackPageView('landing');
  expect(JSON.parse(localStorage.getItem('ayana_local_events'))[0].meta.source).toBe('other');
});

test('guide UTM source stays bounded and survives navigation to signup in the same session', () => {
  expect(getGuideSessionId()).toBeNull();
  window.history.replaceState({}, '', '/nri-parent-care?utm_source=chatgpt.com&utm_campaign=private-do-not-store');
  trackPageView('guide');
  const session = getSessionId();
  expect(getGuideSessionId()).toBe(session);
  window.history.replaceState({}, '', '/signup');
  trackEvent('cta_click', { id: 'guide-primary', guide: 'nri-parent-care' });
  trackPageView('signup');
  const events = JSON.parse(localStorage.getItem('ayana_local_events'));
  expect(events.map(e => e.session_id)).toEqual([session, session, session]);
  expect(events[0].meta.source).toBe('chatgpt');
  expect(events[2].meta.source).toBe('chatgpt');
  expect(JSON.stringify(events)).not.toContain('private-do-not-store');
});
